#### 3. **图片生成与展示**
```tsx
const ImageDisplay = ({ imageData, status }: {
  imageData: string | null;
  status: ImageGenStatus;
}) => {
  if (status === 'generating') {
    return <ProgressBar />;
  }

  return imageData ? (
    <div className="image-container">
      <img 
        src={`data:image/png;base64,${imageData}`} 
        alt="生成的AI图片"
