```js
/**
 * Compose `middleware` returning
 * a fully valid middleware comprised
 * of all those which are passed.
 *
 * @param {Array} middleware
 * @return {Function}
 * @api public
 */
function compose (middleware) {
  // 校验传入的参数是数组，校验数组中每一项是函数
  if (!Array.isArray(middleware)) throw new TypeError('Middleware stack must be an array!')
  for (const fn of middleware) {
    if (typeof fn !== 'function') throw new TypeError('Middleware must be composed of functions!')
  }

  /**
   * @param {Object} context
   * @return {Promise}
   * @api public
   */

  return function (context, next) {
    // last called middleware #
    let index = -1
    return dispatch(0)
    function dispatch (i) {
      // 一个函数中多次调用报错
      // await next()
      // await next()
      if (i <= index) return Promise.reject(new Error('next() called multiple times'))
      index = i
      // 取出数组里的 fn1, fn2, fn3...
      let fn = middleware[i]
      // 最后 相等，next 为 undefined
      if (i === middleware.length) fn = next
      // 直接返回 Promise.resolve()
      if (!fn) return Promise.resolve()
      try {
        return Promise.resolve(fn(context, dispatch.bind(null, i + 1)))
      } catch (err) {
        return Promise.reject(err)
      }
    }
  }
}


```

e834149b-923e-4565-8c26-2a43a5b98085.explanation:
## 题目分析

* 判断s和t的长度是否相等，若不相等，则s和t绝对不是变位词
* 判断s和t是否相等，若相等，则s和t中每个字符出现的次数相同且字符顺序完全相同，s和t不是变位词
* 若s和t不相等但长度相等，可以使用多种方法进行判断

下面介绍两种常见的实现方法：

## 方法一

* 搜集s字符串各个字符数量
* 遍历t字符串，递减数组各个字符数量
* 若有字符数量为负，则为无效，否则是有效

```js
/**
 * @param {string} s
 * @param {string} t
 * @return {boolean}
 */
var isAnagram = function(s, t) {
    if(s === t || s.length != t.length) {
        return false
    }
    let table = new Array(26).fill(0)
    for(let i = 0; i < s.length; i ++) {
        table[s.charCodeAt(i) - 'a'.charCodeAt(0)] ++
    }
    for(let i = 0; i < t.length; i ++) {
        table[t.charCodeAt(i) - 'a'.charCodeAt(0)] --
        if(table[t.charCodeAt(i) - 'a'.charCodeAt(0)] < 0) {
            return false
        }
    }
    return true
};
```

##  方法二

我们可以对字符串 s 和 t 分别排序，看排序后的字符串是否相等。

```js
var isAnagram = function(s, t) {
    return s.length == t.length && s !== t && [...s].sort().join('') === [...t].sort().join('')
};
```

