```javascript
const versions = ['0.1.1', '2.3.3', '0.302.1', '4.2', '4.3.5', '4.3.4.5'];

versions.sort((a, b) => {
    // 将版本号拆分为数组
    const arrA = a.split('.').map(Number);
    const arrB = b.split('.').map(Number);

    // 找出需要比较的最长长度
    const maxLength = Math.max(arrA.length, arrB.length);

    // 逐位比较
    for (let i = 0; i < maxLength; i++) {
        // 如果某一方的版本号已经用完，则默认其后面的位都是0
        const numA = i < arrA.length ? arrA[i] : 0;
        const numB = i < arrB.length ? arrB[i] : 0;

        if (numA !== numB) {
            return numA - numB;
        }
    }

    // 如果所有位都相同，则视为相等
    return 0;
});

console.log(versions);
// 预期输出: ['0.1.1', '0.302.1', '2.3.3', '4.2', '4.3.5', '4.3.4.5']

0295b261-f56a-41fd-847b-7f6947284279.explanation:
`useTimeout` 是可以在函数式组件中，处理 `setTimeout` 计时器函数

## 解决了什么问题？

如果直接在函数式组件中使用 `setTimeout` ，会遇到以下问题：

* 多次调用setTimeout  

```js  
 function App() {  
    const [state, setState] = useState(1);  
    setTimeout(() => {  
        setState(state + 1);  
    }, 3000);  
    return (  
        // 我们原本的目的是在页面渲染完3s后修改一下state，但是你会发现当state+1后，触发了页面的重新渲染，就会重新有一个3s的定时器出现来给state+1，既而变成了每3秒+1。  
        <div> {state} </div>  
    );  
  }; 
```

* hooks 的闭包缺陷  

```js  
function App() {  
  const [count, setCount] = useState(0)  
  const [countTimeout, setCountTimeout] = useState(0)  
  useEffect(() => {  
      setTimeout(() => {  
          setCountTimeout(count)  
      }, 3000)  
      setCount(5)  
  }, [])  
  return (  
       //count发生了变化，但是3s后setTimout的count却还是0  
      <div>  
          Count: {count}  
          <br />  
          setTimeout Count: {countTimeout}  
      </div>  
  )  
}
```

## useTimeout 实现

```js
function useTimeout(callback, delay) {
  const memorizeCallback = useRef();

  useEffect(() => {
    memorizeCallback.current = callback;
  }, [callback]);

  useEffect(() => {
    if (delay !== null) {
      const timer = setTimeout(() => {
        memorizeCallback.current();
      }, delay);
      return () => {
        clearTimeout(timer);
      };
    }
  }, [delay]);
};
```

## 如何使用

```js
  // callback 回调函数， delay 延迟时间
  useTimeout(callback, delay);
```

