var component = normalizer(  
  script,  
  render,  
  staticRenderFns,  
  false,  
  null,  
  "7ba5bd90",  
  null  

)  
/* hot reload */  
// .vue 文件的 script 区域块更改时， 客户端执行这一段代码  
