```js
function getType(value) {
  // 判断数据是 null 的情况
  if (value === null) {
    return value + "";
  }

  // 判断数据是引用类型的情况
  if (typeof value === "object") {
    let valueClass = Object.prototype.toString.call(value),
      type = valueClass.split(" ")[1].split("");

    type.pop();

    return type.join("").toLowerCase();
  } else {
    // 判断数据是基本数据类型的情况和函数的情况
    return typeof value;
  }
}
```

1ea15cb6-7aa1-4d94-8bae-f20fa5594c87.explanation:
setInterval 的作用是每隔一段指定时间执行一个函数，但是这个执行不是真的到了时间立即执行，它真正的作用是每隔一段时间将事件加入事件队列中去，只有当当前的执行栈为空的时候，才能去从事件队列中取出事件执行。所以可能会出现这样的情况，就是当前执行栈执行的时间很长，导致事件队列里边积累多个定时器加入的事件，当执行栈结束的时候，这些事件会依次执行，因此就不能到间隔一段时间执行的效果。

针对 setInterval 的这个缺点，我们可以使用 setTimeout 递归调用来模拟 setInterval，这样我们就确保了只有一个事件结束了，我们才会触发下一个定时器事件，这样解决了 setInterval 的问题。

```js
// 思路是使用递归函数，不断地去执行 setTimeout 从而达到 setInterval 的效果

function mySetInterval(fn, timeout) {
  // 控制器，控制定时器是否继续执行
  var timer = {
    flag: true
  };

  // 设置递归函数，模拟定时器执行。
  function interval() {
    if (timer.flag) {
      fn();
      setTimeout(interval, timeout);
    }
  }

  // 启动定时器
  setTimeout(interval, timeout);

  // 返回控制器
  return timer;
}

```

1ea15cb6-7aa1-4d94-8bae-f20fa5594c87.pivot:
```javascript
function setIntervalWithSetTimeout(callback, interval) {
  let timeoutId;
  let lastExecutionTime = 0;
  function scheduleNextExecution() {
    timeoutId = setTimeout(() => {
      callback();
      lastExecutionTime = Date.now();
      scheduleNextExecution();
    }, interval - (Date.now() - lastExecutionTime));
  }
  scheduleNextExecution();
  return {
    cancel: function() {
      clearTimeout(timeoutId);
    }
  };
}
// 使用示例
const intervalId = setIntervalWithSetTimeout(() => {
  console.log('每隔500毫秒执行一次');
}, 500);
// 停止定时器
setTimeout(() => {
  intervalId.cancel();
}, 3000);
```

6efa769a-3eb9-44ea-bd7c-01c5c991000f.explanation:
在JavaScript中实现拖拽功能，通常需要监听几个关键的事件：`mousedown`（或`touchstart`对于移动设备）、`mousemove`（或`touchmove`）、`mouseup`（或`touchend` 和 `touchcancel`）以及`mouseover`（可选，用于处理元素边界外的移动）。以下是一个基本的拖拽功能的实现步骤：

### 1. HTML 结构

首先，你需要一个可以拖拽的元素。

```html
<div id="draggable" style="width: 100px; height: 100px; background-color: red; position: absolute; cursor: pointer;">拖拽我</div>
```

### 2. CSS 样式

在上面的HTML中，我已经简单设置了样式，使元素可拖动并有一个明显的背景色。

### 3. JavaScript 实现

接下来，我们用JavaScript来添加拖拽逻辑。

```javascript
let selected = null; // 当前被选中的拖拽元素
let x_pos = 0; // 初始X位置
let y_pos = 0; // 初始Y位置
let x_elem = 0; // 鼠标按下时的X位置
let y_elem = 0; // 鼠标按下时的Y位置

// 绑定mousedown事件
document.getElementById("draggable").addEventListener("mousedown", dragMouseDown, false);

function dragMouseDown(e) {
    e = e || window.event;
    e.preventDefault(); // 阻止默认行为（如链接的跳转）
    // 获取拖拽的元素
    selected = this;
    x_elem = x_pos = e.clientX - parseInt(selected.style.left, 10);
    y_elem = y_pos = e.clientY - parseInt(selected.style.top, 10);

    // 绑定mousemove和mouseup事件到整个文档，以便在整个页面上拖动
    document.documentElement.addEventListener("mousemove", dragMouseMove, false);
    document.documentElement.addEventListener("mouseup", closeDragElement, false);
}

function dragMouseMove(e) {
    e = e || window.event;
    e.preventDefault();
    // 计算新的位置
    x_pos = e.clientX - x_elem;
    y_pos = e.clientY - y_elem;

    // 设置元素的新位置
    selected.style.left = x_pos + "px";
    selected.style.top = y_pos + "px";
}

function closeDragElement() {
    // 停止移动时，移除mousemove和mouseup事件监听器
    document.documentElement.removeEventListener("mousemove", dragMouseMove, false);
    document.documentElement.removeEventListener("mouseup", closeDragElement, false);
    selected = null;
}
```

### 说明

- **mousedown**: 当鼠标按下时，获取当前元素和鼠标相对于元素的位置。然后，将`mousemove`和`mouseup`的监听器绑定到整个文档上，这样你就可以在文档的任何地方拖动元素。
- **mousemove**: 当鼠标移动时，计算元素的新位置，并更新元素的样式。
- **mouseup**: 当鼠标释放时，移除`mousemove`和`mouseup`的监听器，避免不必要的性能消耗。

以上就是在JavaScript中实现拖拽功能的基本方法。你可以根据需要调整样式和逻辑。例如，添加拖拽的边界限制，或者支持触摸设备的拖拽等。

a0e34df4-b603-4b18-bcd6-ebf8c94b3325.explanation:
介绍一种只需遍历一次的实现方式，思路比较简单，主要用到了2个临时变量，分别用于记录当前是否在高优先级运算范围和临时值，然后根据不同优先级的运算符进行不同的处理操作。

具体的代码如下：

 ```js
 function addBrackets(expression) {
  const resultArr = []

  // 定义运算符
  const symbolArr = ['+', '-', '*', '/']

  // 定义高优先级运算符
  const highLevelSymbolArr = ['*', '/']

  // 判断某个字符串是否是运算符
  const isSymbolFn = (str) => symbolArr.includes(str)

  // 判断某个字符串是否是高优先级运算符
  const isHighLevelSymbolFn = (str) => highLevelSymbolArr.includes(str)

  // 输入表达式的长度
  const expLen = expression.length

  // 标记当前的遍历是否处于高优先级运算符范围
  let isInBracket = false
  // 记录临时值
  let currentNum = ''

  for (let i = 0; i < expLen; i++) {
    const isSymbol = isSymbolFn(expression[i])
    const isHighLevelSymbol = isSymbol && isHighLevelSymbolFn(expression[i])

    // 处理当前字符是运算符的场景
    if (isSymbol) {
      //处理当前字符是高优先级运算符
      if (isHighLevelSymbol) {
        // 如果当前没有被标记为高优先运算符，就在前面加个括号
        if (!isInBracket) {
          currentNum = '(' + currentNum
        }

        // 修改标记状态
        isInBracket = true
        currentNum += expression[i]
      } else {
        // 普通运算符

        if (isInBracket) {
          // 如果之前已经在高优先级运算符范围，就需要标记结束
          resultArr.push(currentNum + ')')
          isInBracket = false
        } else {
          resultArr.push(currentNum)
        }
        resultArr.push(expression[i])
        currentNum = ''
      }
    } else {
      // 如果是数字，就直接进行记录
      currentNum = currentNum + expression[i]
    }
  }

  if (currentNum) {
    resultArr.push(currentNum + (isInBracket ? ')' : ''))
  }

  return resultArr.join('')
}

 ```

 另外还可以使用滑动窗口的思路来实现：

 ![滑动窗口实现](https://pic.rmb.bdstatic.com/bjh/0531a9146d945741a3368bf59f197c0d.jpeg)

## 使用正则实现（2022/10/30更新）

有小伙伴提供了一种正则表达式的实现方式，供大家参考：

```js
let text = '11+2-34+5/24+10/5+10/512'; 
text.match(/([0-9]{1,}[*|/]){1,}[0-9]{1,}/g).forEach((item)=>{ 
	text = text.replace(item,`(${item})`) 
})
console.log(text); // '11+2-34+(5/24)+(10/5)+(10/512)'
```

